INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('ISO-5667-6', '2015', 'S7_1', 'Probenahmeposition nach §7.1: mindestens 30 cm über der Sohle und eine ähnliche Distanz unter der Oberfläche', '§7.1', NULL, ARRAY['regla']::text[], '[{"name":"height_above_bed_min_cm","type":"number","unit":"cm"},{"name":"depth_below_surface_min_cm","type":"number","unit":"cm"},{"name":"gedruckt","type":"string"},{"name":"modal","type":"string"}]'::jsonb, 'anhaltswert', 'Generalmente, se debería evitar el muestreo en o cerca de la superficie, en el fondo, en la orilla, en
áreas estancadas y estanques. Es necesario tener especial precaución de no perturbar los sedimentos
del fondo y evitar películas no representativas en la superficie. Siempre que sea posible, las muestras
obtenidas de posiciones al menos 30 cm por encima del fondo de un curso de agua y a una distancia
similar debajo de la superficie, suelen ser satisfactorias. — remolinos de agua. Siempre que sea posible, las muestras de agua se deberían recoger a alrededor
de 30 cm por debajo de la superficie, o de otra manera, a media altura entre el lecho y la superficie.', 'imported_unverified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'general', '{"regla":"general"}'::jsonb, NULL, 'Position im Gewässer: ≥ 30 cm über der Sohle und eine ähnliche Distanz unter der Oberfläche (§7.1)', 0, '{"height_above_bed_min_cm":30,"depth_below_surface_min_cm":30,"gedruckt":"al menos 30 cm por encima del fondo de un curso de agua y a una distancia similar debajo de la superficie","modal":"suelen ser satisfactorias"}'::jsonb, 'Generalmente, se debería evitar el muestreo en o cerca de la superficie, en el fondo, en la orilla, en
áreas estancadas y estanques. Es necesario tener especial precaución de no perturbar los sedimentos
del fondo y evitar películas no representativas en la superficie. Siempre que sea posible, las muestras
obtenidas de posiciones al menos 30 cm por encima del fondo de un curso de agua y a una distancia
similar debajo de la superficie, suelen ser satisfactorias.' FROM regulation_tables WHERE standard_code = 'ISO-5667-6' AND edition = '2015' AND table_code = 'S7_1'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('ISO-5667-6', '2015', 'S5_1_3', 'Fließzeitmessung nach §5.1.3: mindestens fünf Durchflüsse, Extrapolation höchstens 10 %', '§5.1.3', NULL, ARRAY['regla']::text[], '[{"name":"flows_min","type":"number"},{"name":"flows_min_gedruckt","type":"string"},{"name":"extrapolation_max_pct","type":"number","unit":"%"},{"name":"modal","type":"string"}]'::jsonb, 'anhaltswert', 'Al determinar el tiempo de viaje, se debería utilizar uno de los tres métodos principales,
específicamente el uso de flotadores de superficie (ver ISO 748), el uso de trazadores
(ver ISO 9555), la medición del caudal con conocimiento de las áreas de sección transversal
(ver ISO 748 e ISO 1070). — Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de
viaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que
se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la
extrapolación fuera del 10% de un valor de medición del caudal puede proporcionar información
incorrecta sobre el tiempo de viaje.', 'imported_unverified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'travel_time', '{"regla":"travel_time"}'::jsonb, NULL, 'Fließzeit: Messungen bei mindestens fünf verschiedenen Durchflüssen; Extrapolation außerhalb von 10 % unsicher (§5.1.3)', 0, '{"flows_min":5,"flows_min_gedruckt":"cinco","extrapolation_max_pct":10,"modal":"se deberían realizar"}'::jsonb, 'Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de
viaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que
se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la
extrapolación fuera del 10% de un valor de medición del caudal puede proporcionar información
incorrecta sobre el tiempo de viaje.' FROM regulation_tables WHERE standard_code = 'ISO-5667-6' AND edition = '2015' AND table_code = 'S5_1_3'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('ISO-5667-6', '2015', 'S5_1_4', 'Heterogenitätstest nach §5.1.4: etwa sechs Proben im 90-%-Durchflussteil, mindestens drei Durchflüsse', '§5.1.4', NULL, ARRAY['regla']::text[], '[{"name":"flow_share_pct","type":"number","unit":"%"},{"name":"samples_approx","type":"number"},{"name":"samples_gedruckt","type":"string"},{"name":"flows_min","type":"number"},{"name":"flows_min_gedruckt","type":"string"},{"name":"modal","type":"string"}]'::jsonb, 'anhaltswert', 'Si no resulta posible encontrar tal sitio de muestreo, en el sitio escogido se deberían tomar las muestras
de los puntos necesarios para garantizar resultados representativos. Idealmente, las muestras se
deberían tomar de muchos puntos diferentes, sin embargo, se sugiere el siguiente enfoque para limitar — la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran
parte (alrededor del 90%) de los pasos totales de flujo, se decide aproximadamente. Dentro de esa
parte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes', 'imported_unverified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'heterogeneity', '{"regla":"heterogeneity"}'::jsonb, NULL, 'Heterogenitätstest: ≈ 6 Proben über den Querschnittsteil mit ≈ 90 % des Durchflusses, bei ≥ 3 Durchflüssen (§5.1.4)', 0, '{"flow_share_pct":90,"samples_approx":6,"samples_gedruckt":"aproximadamente seis","flows_min":3,"flows_min_gedruckt":"al menos tres","modal":"se deberían tomar"}'::jsonb, 'la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran
parte (alrededor del 90%) de los pasos totales de flujo, se decide aproximadamente. Dentro de esa
parte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes
ríos podrían requerir más muestras laterales y verticales. Para determinar si algunas diferencias
aparentes entre las muestras son provocadas por la distribución no homogénea o por errores analíticos,
es necesario un análisis estadístico de los resultados. Todas esas muestras deberían ser recogidas
lo más cercanas al mismo tiempo como sea posible, para evitar los efectos de la variación temporal.
De preferencia, las muestras se deberían tomar de al menos tres caudales correspondientes a lo más
cerca posible de los flujos mínimos, modales y máximos esperados durante el período de las pruebas.' FROM regulation_tables WHERE standard_code = 'ISO-5667-6' AND edition = '2015' AND table_code = 'S5_1_4'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('ISO-5667-6', '2015', 'S10_8', 'Gesamtzeit der Inkremente nach §10.8: weniger als 5 min', '§10.8', NULL, ARRAY['regla']::text[], '[{"name":"total_time_max_min","type":"number","unit":"min"},{"name":"comparator","type":"string"},{"name":"modal","type":"string"}]'::jsonb, 'anhaltswert', 'simples. Para la muestra que se considera como simple y discreta, el tiempo total para todos los
incrementos que se adopten deberían ser tal que no se esperaría ningún cambio en la composición
del río. Si esto no se conoce, el tiempo para todos los incrementos que se adopten debería ser menor
que 5 min.', 'imported_unverified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'incremental', '{"regla":"incremental"}'::jsonb, NULL, 'Inkrementelle Probenahme: Gesamtzeit aller Inkremente < 5 min, wenn keine Änderung der Zusammensetzung bekannt ist (§10.8)', 0, '{"total_time_max_min":5,"comparator":"<","modal":"debería ser menor"}'::jsonb, 'simples. Para la muestra que se considera como simple y discreta, el tiempo total para todos los
incrementos que se adopten deberían ser tal que no se esperaría ningún cambio en la composición
del río. Si esto no se conoce, el tiempo para todos los incrementos que se adopten debería ser menor
que 5 min.' FROM regulation_tables WHERE standard_code = 'ISO-5667-6' AND edition = '2015' AND table_code = 'S10_8'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
